Pseudocode:
# base.py
@dataclass
class SignalResult:
    signal_name: str
    value: float
    satisfied: bool
    details: dict

class Signal(ABC):
    name: str
    @abstractmethod
    def calculate(self, polymarket_odds: dict, orbitexch_odds: dict) -> SignalResult

# spread.py
class SpreadSignal(Signal):
    name = 'spread'
    def __init__(self, threshold: float = 0.02)
    def calculate(self, poly_odds, orbit_odds) -> SignalResult:
        # 计算 poly_bid vs orbit_back 价差
        spread = (orbit_back - poly_bid) / poly_bid
        return SignalResult(satisfied=spread > threshold)

# arbitrage.py
class ArbitrageSignal(Signal):
    name = 'arbitrage'
    def __init__(self, min_profit: float = 0.01)
    def calculate(self, poly_odds, orbit_odds) -> SignalResult:
        # 套利计算: poly买入 + orbit卖出(lay)
        profit = 1/poly_ask - 1/orbit_lay
        return SignalResult(satisfied=profit > min_profit)

