class OddsSubscriptionService:
    def __init__(self):
        ...
        self._strategy_callbacks: list[Callable] = []

    def register_strategy_callback(self, callback: Callable[[str, str, dict], None]):
        '''注册策略回调，callback(pair_id, venue, odds_data)'''
        self._strategy_callbacks.append(callback)

    def _notify_strategy_callbacks(self, pair_id: str, venue: str, odds_data: dict):
        for callback in self._strategy_callbacks:
            try:
                callback(pair_id, venue, odds_data)
