Pseudocode:
router = APIRouter(prefix='/api/strategy', tags=['strategy'])

@router.get('/config')
async def get_strategy_config():
    return app_state.get_strategy_config()

@router.put('/config')
async def update_strategy_config(body: StrategyConfigUpdate):
    return app_state.update_strategy_config(body.dict())

@router.get('/signals/{pair_id}')
async def get_signals(pair_id: str):
    service = app_state.get_strategy_service()
    return service.get_signals(pair_id)

@router.get('/opportunities')
async def get_opportunities():
    service = app_state.get_strategy_service()
    return {'opportunities': service.get_opportunities()}

